=== FILE: irq_ctrl_cov_tb.sv ===
`timescale 1ns / 1ps
// Coverage testbench for irq_ctrl.v (task prj-63d6b8e26c:coverage).
// Extends the approved idle testbench (irq_ctrl_idle_tb.sv). One stimulus stream drives two
// instances of the approved RTL:
//   dut_a  N = 8   the configuration of the approved testbench (src[7:0])
//   dut_b  N = 32  every bit of rdata, irq_id and the per-source registers is reachable
// A cycle-accurate reference model predicts rdata, irq and irq_id of both instances; they are
// compared 1 ns before and 1 ns after every rising edge, and directed reads compare register
// values against fixed expectations.
// Not reachable by design (justified in the coverage report): unused_wdata is constant 0; in
// dut_a rdata[30:8] and irq_id[4:3] are constant 0; in dut_b an out-of-range acknowledge
// (wdata[4:0] >= N) cannot occur.
module irq_ctrl_cov_tb;
    localparam logic [31:0] MASK_A = 32'h0000_00FF;  // dut_a, N = 8
    localparam logic [31:0] MASK_B = 32'hFFFF_FFFF;  // dut_b, N = 32
    localparam logic [1:0]  A_ENABLE = 2'd0, A_MODE = 2'd1, A_PENDING = 2'd2, A_CLAIM = 2'd3;

    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic [31:0] src = '0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata_a, rdata_b;
    logic        irq_a, irq_b;
    logic [4:0]  irq_id_a, irq_id_b;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    // Reference model state (reset at the first rising edge, before any comparison).
    logic [31:0] en_a, md_a, pd_a, sq_a;
    logic [31:0] en_b, md_b, pd_b, sq_b;

    irq_ctrl #(.N(8)) dut_a (.clk(clk), .rst_n(rst_n), .src(src[7:0]), .we(we), .addr(addr),
                             .wdata(wdata), .rdata(rdata_a), .irq(irq_a), .irq_id(irq_id_a));
    irq_ctrl #(.N(32)) dut_b (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr),
                              .wdata(wdata), .rdata(rdata_b), .irq(irq_b), .irq_id(irq_id_b));

    always #5 clk = ~clk;

    // ---------------------------------------------------------------- reference model
    function automatic logic [31:0] next_pending(input logic [31:0] msk, input logic [5:0] n,
                                                 input logic [31:0] p, input logic [31:0] mo,
                                                 input logic [31:0] sq, input logic [31:0] s,
                                                 input logic w, input logic [1:0] a,
                                                 input logic [31:0] d);
        logic [31:0] sm, det, clr;
        sm  = s & msk;
        det = ((mo & sm & ~sq) | (~mo & sm)) & msk;
        clr = 32'd0;
        if (w && a == 2'd2) clr = d & msk;
        if (w && a == 2'd3 && {1'b0, d[4:0]} < n) clr = clr | (32'd1 << d[4:0]);
        return (det | (p & ~clr)) & msk;
    endfunction

    function automatic logic [4:0] lowest(input logic [31:0] act);
        logic [4:0] r;
        logic [5:0] k;
        logic       found;
        r = 5'd0;
        found = 1'b0;
        for (k = 6'd0; k < 6'd32; k = k + 6'd1) begin
            if (!found && act[k[4:0]]) begin
                r = k[4:0];
                found = 1'b1;
            end
        end
        return r;
    endfunction

    function automatic logic [31:0] exp_rdata(input logic [1:0] a, input logic [31:0] e,
                                              input logic [31:0] mo, input logic [31:0] p);
        logic [31:0] act, r;
        act = e & p;
        case (a)
            2'd0:    r = e;
            2'd1:    r = mo;
            2'd2:    r = p;
            default: r = {(|act), 26'd0, lowest(act)};
        endcase
        return r;
    endfunction

    always @(posedge clk) begin
        if (!rst_n) begin
            en_a <= 32'd0; md_a <= 32'd0; pd_a <= 32'd0; sq_a <= 32'd0;
            en_b <= 32'd0; md_b <= 32'd0; pd_b <= 32'd0; sq_b <= 32'd0;
        end else begin
            pd_a <= next_pending(MASK_A, 6'd8,  pd_a, md_a, sq_a, src, we, addr, wdata);
            pd_b <= next_pending(MASK_B, 6'd32, pd_b, md_b, sq_b, src, we, addr, wdata);
            sq_a <= src & MASK_A;
            sq_b <= src & MASK_B;
            if (we && addr == A_ENABLE) begin
                en_a <= wdata & MASK_A;
                en_b <= wdata & MASK_B;
            end
            if (we && addr == A_MODE) begin
                md_a <= wdata & MASK_A;
                md_b <= wdata & MASK_B;
            end
        end
    end

    // ---------------------------------------------------------------- checkers
    task automatic check_one(input int tag, input int n, input logic [31:0] got_rd,
                             input logic got_irq, input logic [4:0] got_id,
                             input logic [31:0] e, input logic [31:0] mo, input logic [31:0] p);
        logic [31:0] act, exp_rd;
        act = e & p;
        exp_rd = exp_rdata(addr, e, mo, p);
        checks++;
        if (got_rd !== exp_rd || got_irq !== (|act) || got_id !== lowest(act)) begin
            errors++;
            if (errors <= 20)
                $display("MISMATCH N=%0d tag=%0d t=%0t addr=%0d rdata=%h/%h irq=%b/%b irq_id=%0d/%0d",
                         n, tag, $time, addr, got_rd, exp_rd, got_irq, (|act), got_id, lowest(act));
        end
    endtask

    task automatic check_all(input int tag);
        check_one(tag, 8,  rdata_a, irq_a, irq_id_a, en_a, md_a, pd_a);
        check_one(tag, 32, rdata_b, irq_b, irq_id_b, en_b, md_b, pd_b);
    endtask

    // One clock cycle: called at a falling edge, drives the inputs, checks before and after the
    // rising edge, returns at the next falling edge.
    task automatic step(input logic [31:0] s, input logic w, input logic [1:0] a,
                        input logic [31:0] d, input int tag);
        src = s; we = w; addr = a; wdata = d;
        #1;
        check_all(tag);
        @(posedge clk);
        #1;
        check_all(tag);
        @(negedge clk);
    endtask

    // Directed read with fixed expectations for both instances. Called at a falling edge; holds
    // src, drops we and returns at the next falling edge (that edge leaves the state unchanged).
    task automatic expect_rd(input logic [1:0] a, input logic [31:0] exp_a, input logic [31:0] exp_b);
        we = 1'b0;
        addr = a;
        #1;
        checks++;
        if (rdata_a !== exp_a) begin
            errors++;
            if (errors <= 20)
                $display("DIRECTED N=8 t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata_a, exp_a);
        end
        checks++;
        if (rdata_b !== exp_b) begin
            errors++;
            if (errors <= 20)
                $display("DIRECTED N=32 t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata_b, exp_b);
        end
        check_all(100);
        @(negedge clk);
    endtask

    // Register write followed by a directed read back (ENABLE and MODE).
    task automatic wr_rb(input logic [1:0] a, input logic [31:0] d);
        step(src, 1'b1, a, d, 1);
        expect_rd(a, d & MASK_A, d & MASK_B);
    endtask

    // ---------------------------------------------------------------- stimulus
    initial begin : stimulus
        logic [31:0] s, ea, eb, pa, pb;

        // Phase 0: reset wins over writes and active sources.
        @(negedge clk);
        step(32'hFFFF_FFFF, 1'b1, A_ENABLE,  32'hFFFF_FFFF, 0);
        step(32'hFFFF_FFFF, 1'b1, A_MODE,    32'hFFFF_FFFF, 0);
        step(32'h0000_0000, 1'b0, A_PENDING, 32'd0,         0);
        rst_n = 1'b1;
        expect_rd(A_ENABLE,  32'd0, 32'd0);
        expect_rd(A_MODE,    32'd0, 32'd0);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        expect_rd(A_CLAIM,   32'd0, 32'd0);

        // Phase 1: ENABLE and MODE patterns (bits N and up read as zero for N = 8).
        wr_rb(A_ENABLE, 32'hFFFF_FFFF);
        wr_rb(A_ENABLE, 32'h0000_0000);
        wr_rb(A_ENABLE, 32'hAAAA_AAAA);
        wr_rb(A_ENABLE, 32'h5555_5555);
        wr_rb(A_MODE,   32'hFFFF_FFFF);
        wr_rb(A_MODE,   32'h0000_0000);
        wr_rb(A_MODE,   32'hAAAA_AAAA);
        wr_rb(A_MODE,   32'h5555_5555);
        expect_rd(A_ENABLE, 32'h0000_0055, 32'h5555_5555);
        step(32'd0, 1'b1, A_PENDING, 32'hFFFF_FFFF, 1);
        step(32'd0, 1'b1, A_CLAIM,   32'd0,         1);
        expect_rd(A_PENDING, 32'd0, 32'd0);

        // Phase 2: level mode, every source alone: detect, claim, hold, W1C.
        wr_rb(A_MODE,   32'h0000_0000);
        wr_rb(A_ENABLE, 32'hFFFF_FFFF);
        for (int k = 0; k < 32; k++) begin
            s  = 32'd1 << k;
            ea = (k < 8) ? (32'h8000_0000 | k) : 32'd0;
            eb = 32'h8000_0000 | k;
            step(s, 1'b0, A_CLAIM, 32'd0, 2);
            expect_rd(A_CLAIM, ea, eb);
            step(32'd0, 1'b0, A_PENDING, 32'd0, 2);
            expect_rd(A_PENDING, s & MASK_A, s);
            step(32'd0, 1'b1, A_PENDING, s, 2);
            expect_rd(A_PENDING, 32'd0, 32'd0);
        end

        // Phase 3: level mode, a detection wins over a W1C at the same edge.
        s = 32'h0010_0010;
        step(s, 1'b0, A_PENDING, 32'd0, 3);
        expect_rd(A_PENDING, 32'h0000_0010, 32'h0010_0010);
        step(s, 1'b1, A_PENDING, s, 3);
        expect_rd(A_PENDING, 32'h0000_0010, 32'h0010_0010);
        step(32'd0, 1'b1, A_PENDING, s, 3);
        expect_rd(A_PENDING, 32'd0, 32'd0);

        // Phase 4: fixed priority and acknowledge of every id, upper wdata bits set.
        step(32'hFFFF_FFFF, 1'b0, A_CLAIM, 32'd0, 4);
        step(32'd0,         1'b0, A_CLAIM, 32'd0, 4);
        expect_rd(A_CLAIM, 32'h8000_0000, 32'h8000_0000);
        for (int k = 0; k < 32; k++) begin
            step(32'd0, 1'b1, A_CLAIM, 32'hFFFF_FFE0 | k, 4);
            pb = (k == 31) ? 32'd0 : (32'hFFFF_FFFF << (k + 1));
            pa = (32'h0000_00FF << (k + 1)) & MASK_A;
            ea = (k < 7)  ? (32'h8000_0000 | (k + 1)) : 32'd0;
            eb = (k < 31) ? (32'h8000_0000 | (k + 1)) : 32'd0;
            expect_rd(A_PENDING, pa, pb);
            expect_rd(A_CLAIM, ea, eb);
        end
        // Out-of-range acknowledge for N = 8 is ignored; N = 32 clears the bit.
        step(32'hFFFF_FFFF, 1'b0, A_PENDING, 32'd0, 4);
        step(32'd0,         1'b0, A_PENDING, 32'd0, 4);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'hFFFF_FFFF);
        step(32'd0, 1'b1, A_CLAIM, 32'd9, 4);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'hFFFF_FDFF);
        step(32'd0, 1'b1, A_CLAIM, 32'd31, 4);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'h7FFF_FDFF);
        step(32'd0, 1'b1, A_CLAIM, 32'h0000_0025, 4);  // wdata[4:0] = 5
        expect_rd(A_PENDING, 32'h0000_00DF, 32'h7FFF_FDDF);
        // Enable masking of the priority.
        step(32'd0, 1'b1, A_ENABLE, 32'hF0F0_F0F0, 4);
        expect_rd(A_CLAIM, 32'h8000_0004, 32'h8000_0004);
        step(32'd0, 1'b1, A_ENABLE, 32'hFFFF_0000, 4);
        expect_rd(A_CLAIM, 32'd0, 32'h8000_0010);
        step(32'd0, 1'b1, A_ENABLE, 32'hC000_0000, 4);
        expect_rd(A_CLAIM, 32'd0, 32'h8000_001E);
        step(32'd0, 1'b1, A_ENABLE, 32'h0000_0000, 4);
        expect_rd(A_CLAIM, 32'd0, 32'd0);
        expect_rd(A_PENDING, 32'h0000_00DF, 32'h7FFF_FDDF);
        step(32'd0, 1'b1, A_PENDING, 32'hFFFF_FFFF, 4);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        step(32'd0, 1'b1, A_ENABLE, 32'hFFFF_FFFF, 4);

        // Phase 5: rising-edge mode.
        wr_rb(A_MODE, 32'hFFFF_FFFF);
        for (int k = 0; k < 32; k++) begin
            s = 32'd1 << k;
            step(s, 1'b0, A_PENDING, 32'd0, 5);
            expect_rd(A_PENDING, s & MASK_A, s);
            step(s, 1'b1, A_PENDING, s, 5);           // held high: no new edge, cleared
            expect_rd(A_PENDING, 32'd0, 32'd0);
            step(32'd0, 1'b0, A_PENDING, 32'd0, 5);
        end
        // An edge wins over a W1C at the same edge.
        step(32'h0000_0004, 1'b1, A_PENDING, 32'h0000_0004, 5);
        expect_rd(A_PENDING, 32'h0000_0004, 32'h0000_0004);
        step(32'h0000_0004, 1'b1, A_PENDING, 32'h0000_0004, 5);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        step(32'd0, 1'b0, A_PENDING, 32'd0, 5);
        // An edge wins over an acknowledge at the same edge.
        step(32'h0000_0008, 1'b1, A_CLAIM, 32'd3, 5);
        expect_rd(A_PENDING, 32'h0000_0008, 32'h0000_0008);
        expect_rd(A_CLAIM, 32'h8000_0003, 32'h8000_0003);
        step(32'h0000_0008, 1'b1, A_CLAIM, 32'd3, 5);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        step(32'd0, 1'b0, A_PENDING, 32'd0, 5);
        // A one-cycle pulse stays latched.
        step(32'h0001_0001, 1'b0, A_PENDING, 32'd0, 5);
        step(32'd0,         1'b0, A_PENDING, 32'd0, 5);
        expect_rd(A_PENDING, 32'h0000_0001, 32'h0001_0001);
        step(32'd0, 1'b1, A_PENDING, 32'hFFFF_FFFF, 5);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        // All sources rise together.
        step(32'hFFFF_FFFF, 1'b0, A_CLAIM, 32'd0, 5);
        expect_rd(A_CLAIM, 32'h8000_0000, 32'h8000_0000);
        step(32'hFFFF_FFFF, 1'b1, A_PENDING, 32'hFFFF_FFFF, 5);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        step(32'd0, 1'b0, A_PENDING, 32'd0, 5);

        // Phase 6: mixed modes, then a mode change with the sources held high.
        wr_rb(A_MODE, 32'h5555_5555);
        step(32'hFFFF_FFFF, 1'b0, A_PENDING, 32'd0, 6);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'hFFFF_FFFF);
        step(32'hFFFF_FFFF, 1'b1, A_PENDING, 32'hFFFF_FFFF, 6);
        expect_rd(A_PENDING, 32'h0000_00AA, 32'hAAAA_AAAA);
        expect_rd(A_CLAIM, 32'h8000_0001, 32'h8000_0001);
        step(32'hFFFF_FFFF, 1'b1, A_MODE, 32'h0000_0000, 6);
        step(32'hFFFF_FFFF, 1'b0, A_PENDING, 32'd0, 6);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'hFFFF_FFFF);
        step(32'd0, 1'b1, A_PENDING, 32'hFFFF_FFFF, 6);
        expect_rd(A_PENDING, 32'd0, 32'd0);

        // Phase 7: reset in the middle of activity.
        wr_rb(A_MODE, 32'h0F0F_0F0F);
        step(32'hFFFF_FFFF, 1'b0, A_CLAIM, 32'd0, 7);
        expect_rd(A_CLAIM, 32'h8000_0000, 32'h8000_0000);
        rst_n = 1'b0;
        step(32'hFFFF_FFFF, 1'b1, A_ENABLE, 32'hFFFF_FFFF, 7);
        expect_rd(A_ENABLE,  32'd0, 32'd0);
        expect_rd(A_MODE,    32'd0, 32'd0);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        expect_rd(A_CLAIM,   32'd0, 32'd0);
        rst_n = 1'b1;
        step(32'hFFFF_FFFF, 1'b0, A_PENDING, 32'd0, 7);
        expect_rd(A_PENDING, 32'h0000_00FF, 32'hFFFF_FFFF);
        expect_rd(A_CLAIM, 32'd0, 32'd0);
        step(32'd0, 1'b1, A_PENDING, 32'hFFFF_FFFF, 7);
        expect_rd(A_PENDING, 32'd0, 32'd0);
        step(32'd0, 1'b0, A_CLAIM, 32'd0, 8);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
